"use client";

import { useCallback, useEffect, useState } from "react";

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";
const PAGE_SIZE = 10;
const REFRESH_MS = 5000;

type UploadLog = {
  id: string;
  action: string;
  bucket_name: string;
  object_key: string;
  object_size: number;
  status: "pending" | "processed" | "failed";
  event_time: string;
  created_at: string;
};

type Pagination = {
  total_records: number;
  total_pages: number;
  current_page: number;
};

function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let size = bytes / 1024;
  let i = 0;
  while (size >= 1024 && i < units.length - 1) {
    size /= 1024;
    i++;
  }
  return `${size.toFixed(1)} ${units[i]}`;
}

function formatTime(value: string) {
  return new Date(value).toLocaleString("en-GB", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

const statusStyle: Record<string, string> = {
  pending: "border-amber-700 text-amber-800",
  processed: "border-green-800 text-green-800",
  failed: "border-red-800 text-red-800",
};

export default function Home() {
  const [logs, setLogs] = useState<UploadLog[]>([]);
  const [pagination, setPagination] = useState<Pagination | null>(null);
  const [page, setPage] = useState(1);
  const [error, setError] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [uploadMsg, setUploadMsg] = useState("");
  const [uploading, setUploading] = useState(false);

  const loadLogs = useCallback(async () => {
    try {
      const res = await fetch(`${API_URL}/api/r2?page=${page}&limit=${PAGE_SIZE}`);
      const json = await res.json();
      if (!json.success) throw new Error(json.message);
      setLogs(json.data.logs ?? []);
      setPagination(json.data.pagination);
      setError("");
    } catch (err) {
      setError(`Cannot load logs: ${(err as Error).message}`);
    }
  }, [page]);

  useEffect(() => {
    const first = setTimeout(loadLogs, 0);
    const timer = setInterval(loadLogs, REFRESH_MS);
    return () => {
      clearTimeout(first);
      clearInterval(timer);
    };
  }, [loadLogs]);

  async function handleUpload() {
    if (!file) return;
    if (!file.name.endsWith(".tar")) {
      setUploadMsg("Please choose a .tar file.");
      return;
    }

    setUploading(true);
    setUploadMsg("Getting upload URL...");
    try {
      const res = await fetch(`${API_URL}/api/r2/presigned-upload`, { method: "POST" });
      const json = await res.json();
      if (!json.success) throw new Error(json.message);

      setUploadMsg("Uploading to R2...");
      const put = await fetch(json.data.presigned_url, {
        method: "PUT",
        headers: { "Content-Type": "application/x-tar" },
        body: file,
      });
      if (!put.ok) throw new Error(`R2 returned ${put.status}`);

      setUploadMsg(`Uploaded as ${json.data.object_key}. Waiting for the event...`);
      setFile(null);
    } catch (err) {
      setUploadMsg(`Upload failed: ${(err as Error).message}`);
    } finally {
      setUploading(false);
    }
  }

  const totalPages = Math.max(pagination?.total_pages ?? 1, 1);

  return (
    <main className="mx-auto w-full max-w-5xl px-4 py-10">
      <header className="border-b-4 border-double border-stone-800 pb-4 text-center">
        <h1 className="text-4xl font-bold tracking-wide">R2 Upload Logs</h1>
        <p className="mt-1 text-sm italic text-stone-600">
          Cloudflare R2 event trigger test for VirtualLab Scanner Pipeline
        </p>
      </header>

      <section className="mt-8 border border-stone-400 bg-white/60 p-5">
        <h2 className="mb-3 text-lg font-bold">Upload Container Image</h2>
        <div className="flex flex-wrap items-center gap-3">
          <input
            type="file"
            accept=".tar"
            onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            className="text-sm file:mr-3 file:border file:border-stone-700 file:bg-stone-100 file:px-3 file:py-1 file:font-serif"
          />
          <button
            onClick={handleUpload}
            disabled={!file || uploading}
            className="border border-stone-800 bg-stone-800 px-4 py-1 text-stone-50 hover:bg-stone-700 disabled:opacity-40"
          >
            {uploading ? "Uploading..." : "Upload"}
          </button>
        </div>
        {uploadMsg && <p className="mt-3 text-sm text-stone-700">{uploadMsg}</p>}
      </section>

      <section className="mt-8">
        <div className="mb-2 flex items-end justify-between">
          <h2 className="text-lg font-bold">Event Log</h2>
          <div className="flex items-center gap-3 text-sm text-stone-600">
            <span>{pagination?.total_records ?? 0} records, auto refresh every 5s</span>
            <button
              onClick={loadLogs}
              className="border border-stone-700 px-3 py-0.5 hover:bg-stone-200"
            >
              Refresh
            </button>
          </div>
        </div>

        {error && (
          <p className="mb-3 border border-red-800 bg-red-50 px-3 py-2 text-sm text-red-800">
            {error}
          </p>
        )}

        <div className="overflow-x-auto">
          <table className="w-full border-collapse border border-stone-500 bg-white/60 text-sm">
            <thead>
              <tr className="bg-stone-200 text-left">
                <th className="border border-stone-400 px-3 py-2">Event Time</th>
                <th className="border border-stone-400 px-3 py-2">Object Key</th>
                <th className="border border-stone-400 px-3 py-2">Bucket</th>
                <th className="border border-stone-400 px-3 py-2 text-right">Size</th>
                <th className="border border-stone-400 px-3 py-2">Action</th>
                <th className="border border-stone-400 px-3 py-2">Status</th>
              </tr>
            </thead>
            <tbody>
              {logs.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-3 py-8 text-center italic text-stone-500">
                    No events yet. Upload a .tar file to see it here.
                  </td>
                </tr>
              ) : (
                logs.map((log, i) => (
                  <tr key={log.id} className={i % 2 ? "bg-stone-100/70" : ""}>
                    <td className="whitespace-nowrap border border-stone-300 px-3 py-2">
                      {formatTime(log.event_time)}
                    </td>
                    <td className="break-all border border-stone-300 px-3 py-2 font-mono text-xs">
                      {log.object_key}
                    </td>
                    <td className="border border-stone-300 px-3 py-2">{log.bucket_name}</td>
                    <td className="whitespace-nowrap border border-stone-300 px-3 py-2 text-right">
                      {formatSize(log.object_size)}
                    </td>
                    <td className="border border-stone-300 px-3 py-2">{log.action}</td>
                    <td className="border border-stone-300 px-3 py-2">
                      <span
                        className={`border px-2 py-0.5 text-xs uppercase tracking-wider ${statusStyle[log.status] ?? ""}`}
                      >
                        {log.status}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <nav className="mt-4 flex items-center justify-center gap-4 text-sm">
          <button
            onClick={() => setPage((p) => p - 1)}
            disabled={page <= 1}
            className="border border-stone-700 px-3 py-0.5 hover:bg-stone-200 disabled:opacity-40"
          >
            &laquo; Prev
          </button>
          <span>
            Page {page} of {totalPages}
          </span>
          <button
            onClick={() => setPage((p) => p + 1)}
            disabled={page >= totalPages}
            className="border border-stone-700 px-3 py-0.5 hover:bg-stone-200 disabled:opacity-40"
          >
            Next &raquo;
          </button>
        </nav>
      </section>
    </main>
  );
}
